CREATE FUNCTION IF NOT EXISTS h6_tx AS (t) -> SHA256(concat('tx', toString(t)));
CREATE FUNCTION IF NOT EXISTS h6_isprice AS (t) -> t >= 128220180 AND (t % 330) IN (7, 117, 227);
CREATE FUNCTION IF NOT EXISTS h6_pk AS (t) -> toUInt64(3 * (intDiv(t, 330) - 388546) + indexOf([7, 117, 227], t % 330) - 1);
CREATE FUNCTION IF NOT EXISTS h6_pt AS (k) -> toUInt64(330 * (388546 + intDiv(k, 3)) + arrayElement([7, 117, 227], (k % 3) + 1));
CREATE FUNCTION IF NOT EXISTS h6_isloan AS (t) -> t >= 128220180 AND t % 330 = 51 AND (intDiv(t, 330) - 388546) % 3 = 1;
CREATE FUNCTION IF NOT EXISTS h6_lj AS (t) -> toUInt64(intDiv(intDiv(t, 330) - 388546, 3));
CREATE FUNCTION IF NOT EXISTS h6_lt AS (j) -> toUInt64(330 * (388547 + 3 * j) + 51);
CREATE FUNCTION IF NOT EXISTS h6_planted AS (t) -> h6_isprice(t) OR h6_isloan(t);
CREATE FUNCTION IF NOT EXISTS h6_iscash AS (t) -> intDiv(t, 330) BETWEEN 150000 AND 199999 AND (t % 330 = 13 OR (intDiv(t, 330) = 170000 AND t % 330 = 14));
CREATE FUNCTION IF NOT EXISTS h6_cashname AS (t) -> multiIf(t = 330 * 170000 + 13, 'Jonathan', t = 330 * 170000 + 14, 'bitjson', concat('n', leftPad(toString(cityHash64(t, 'nm') % 10000), 7, '0')));
CREATE FUNCTION IF NOT EXISTS h6_cashlb AS (t) -> concat(unhex('6a0401010101'), char(length(h6_cashname(t))), h6_cashname(t), unhex('1501'), substring(SHA256(concat('cp', toString(t))), 1, 20));
CREATE FUNCTION IF NOT EXISTS h6_nout AS (t) -> if(h6_planted(t), greatest(2, arrayElement([1,2,2,2,3,3,4,6], (cityHash64(t, 'n') % 8) + 1)), arrayElement([1,2,2,2,3,3,4,6], (cityHash64(t, 'n') % 8) + 1));
CREATE FUNCTION IF NOT EXISTS h6_nin AS (t) -> if(t % 330 = 0, 1, arrayElement([1,1,1,2,2,3,4,6], (cityHash64(t, 'i') % 8) + 1));
CREATE FUNCTION IF NOT EXISTS h6_addr AS (h) -> if(h % 10 < 2, h % 1000, if(h % 10 < 6, 1000 + (intDiv(h, 10) % 10000000), h));
CREATE FUNCTION IF NOT EXISTS h6_glb AS (t, i) -> multiIf(cityHash64(t, i, 'k') % 100 < 60, concat(unhex('76a914'), substring(SHA256(concat('a', toString(h6_addr(cityHash64(t, i, 'a'))))), 1, 20), unhex('88ac')), cityHash64(t, i, 'k') % 100 < 95, concat(unhex('a914'), substring(SHA256(concat('s', toString(h6_addr(cityHash64(t, i, 'a'))))), 1, 20), unhex('87')), concat(unhex('6a'), toString(SHA256(concat('r', toString(t), toString(i))))));
CREATE FUNCTION IF NOT EXISTS h6_lb AS (t, i) -> multiIf(i = 0 AND h6_isprice(t), concat(unhex('aa20'), SHA256('price'), unhex('87')), i = 0 AND h6_isloan(t), concat(unhex('aa20'), SHA256('loan'), unhex('87')), i = 0 AND h6_iscash(t), h6_cashlb(t), h6_glb(t, i));
CREATE FUNCTION IF NOT EXISTS h6_istoken AS (t, i) -> (i = 0 AND h6_planted(t)) OR cityHash64(t, i, 'tk') % 1000 < 20;
CREATE FUNCTION IF NOT EXISTS h6_catn AS (t, i) -> if(cityHash64(t, i, 'c') % 10 < 3, cityHash64(t, i, 'c') % 5, cityHash64(t, i, 'c') % 5000);
CREATE FUNCTION IF NOT EXISTS h6_cat AS (t, i) -> multiIf(i = 0 AND h6_planted(t), SHA256('paryon'), cityHash64(t, i, 'tk') % 1000 < 20, SHA256(concat('cat', toString(h6_catn(t, i)))), toFixedString(repeat('\0', 32), 32));
CREATE FUNCTION IF NOT EXISTS h6_capn AS (t, i) -> if(h6_istoken(t, i), cityHash64(t, i, 'cap') % 10, 0);
CREATE FUNCTION IF NOT EXISTS h6_cap AS (t, i) -> CAST(multiIf(i = 0 AND h6_planted(t), 'mutable', NOT h6_istoken(t, i), NULL, h6_capn(t, i) < 6, NULL, h6_capn(t, i) < 8, 'none', h6_capn(t, i) = 8, 'mutable', 'minting'), 'Nullable(Enum8(\'none\' = 1, \'mutable\' = 2, \'minting\' = 3))');
CREATE FUNCTION IF NOT EXISTS h6_ft AS (t, i) -> if(NOT (i = 0 AND h6_planted(t)) AND h6_istoken(t, i) AND h6_capn(t, i) < 7, toNullable(toInt64(cityHash64(t, i, 'ft') % 1000000000)), NULL);
CREATE FUNCTION IF NOT EXISTS h6_commit AS (t, i) -> multiIf(i = 0 AND h6_planted(t), toNullable(substring(toString(SHA256(concat('lc', toString(t)))), 1, 27)), h6_istoken(t, i) AND h6_capn(t, i) >= 6, toNullable(substring(toString(SHA256(concat('m', toString(t), toString(i)))), 1, cityHash64(t, i, 'ml') % 41)), NULL);
CREATE FUNCTION IF NOT EXISTS h6_value AS (t, i) -> toInt64(cityHash64(t, i, 'v') % 100000000);
CREATE FUNCTION IF NOT EXISTS h6_seq AS (t) -> toUInt64(1099511627777 + intDiv(intDiv(t, 330), 300));
CREATE FUNCTION IF NOT EXISTS h6_chain AS (t, j) -> j = 0 AND ((h6_isprice(t) AND h6_pk(t) >= 5) OR (h6_isloan(t) AND h6_lj(t) >= 300));
CREATE FUNCTION IF NOT EXISTS h6_prev AS (t, j) -> multiIf(t % 330 = 0, toUInt64(0), j = 0 AND h6_isprice(t) AND h6_pk(t) >= 5, h6_pt(h6_pk(t) - 5), j = 0 AND h6_isloan(t) AND h6_lj(t) >= 300, h6_lt(h6_lj(t) - 300), cityHash64(t, j, 'o') % t);
CREATE FUNCTION IF NOT EXISTS h6_previdx AS (t, j) -> if(h6_chain(t, j), toUInt32(0), if(h6_planted(h6_prev(t, j)) AND cityHash64(t, j, 'oi') % h6_nout(h6_prev(t, j)) = 0, toUInt32(1), toUInt32(cityHash64(t, j, 'oi') % h6_nout(h6_prev(t, j)))));
